import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
const api=await import('../src/reference-engine.mjs').catch(()=>({}));
const read=p=>fs.readFileSync(new URL('../'+p,import.meta.url),'utf8');
const pack=()=>({catalogueText:read('data/bright-stars.json'),manifestText:read('data/registered-starlight/runtime-manifest.json'),assetTexts:Object.fromEntries(['32','64','128'].map(t=>[t,read('data/registered-starlight/V-nside'+t+'.json')]))});
const job=()=>({tier:'32',assetFault:'none',assetRevision:0,observer:{utcMs:Date.UTC(2026,0,15,2),latDeg:28.54,lonDeg:-81.38,pressureHpa:0},options:{view:{type:'camera',width:16,height:24,azDeg:180,altDeg:45},diffuse:{enabled:true,samplesPerAxis:1,allowEstimates:true,residualNight:{kind:'assumed-nonstellar-residual',zenithCdM2:.00014,source:'test assumption',includesRegisteredStarlight:false}}},calendarMask:false,cloudmap:false});
test('serialisable reference engine admits exact bytes and transfers unique linear buffers without duplicate aliases',async()=>{assert.equal(typeof api.ReferenceSkyEngine,'function');const engine=new api.ReferenceSkyEngine(pack()),a=await engine.render(job());assert.equal(a.status,'ready');assert.equal(a.diffuseAsset.mode,'registered');assert.ok(a.timings.renderMs>=0);assert.equal(typeof api.rasterTransferables,'function');const t=api.rasterTransferables(a);assert.equal(t.length,new Set(t).size);assert.ok(t.includes(a.raster.linear.buffer));structuredClone(a,{transfer:t});assert.equal(a.raster.linear.byteLength,0);});
test('missing/corrupt/wrong-version drills degrade only diffuse light, and a valid retry restores exact output',async()=>{assert.equal(typeof api.ReferenceSkyEngine,'function');const e=new api.ReferenceSkyEngine(pack()),j=job(),a=await e.render(j),reference=Array.from(a.raster.linear);for(const fault of ['missing','corrupt','wrong-version']){const b=await e.render({...j,assetFault:fault});assert.equal(b.status,'ready');assert.equal(b.diffuseAsset.mode,'cp6-fallback');assert.equal(b.raster.diffuseState,undefined);assert.ok(b.diffuseAsset.error);const c=await e.render({...j,assetRevision:1});assert.equal(c.diffuseAsset.mode,'registered');assert.deepEqual(Array.from(c.raster.linear),reference);}});
test('new accepted time/location/weather/camera always reprojects; returning to exact inputs restores the frame',async()=>{assert.equal(typeof api.ReferenceSkyEngine,'function');const e=new api.ReferenceSkyEngine(pack()),j=job(),a=await e.render(j);for(const patch of [{observer:{...j.observer,utcMs:j.observer.utcMs+3600000}},{observer:{...j.observer,latDeg:-33.87}},{options:{...j.options,atmosphere:{cloudTransmission:.08}}},{options:{...j.options,view:{...j.options.view,rollDeg:38}}}]){const b=await e.render({...j,...patch});assert.notDeepEqual(b.raster.linear,a.raster.linear);}assert.deepEqual((await e.render(j)).raster.linear,a.raster.linear);e.dispose();await assert.rejects(()=>e.render(j),/disposed/);});
